const API_BASE = "http://localhost:8080/api";

// ---------------------------------------------
// PRODUCTS API
// ---------------------------------------------
export async function fetchProducts() {
  try {
    const res = await fetch(`${API_BASE}/products`);
    return await res.json();
  } catch (err) {
    console.error("Error fetching products:", err);
    return [];
  }
}

export async function fetchFiltered(category) {
  try {
    const res = await fetch(`${API_BASE}/products/category/${category}`);
    return await res.json();
  } catch (err) {
    console.error("Error fetching filtered products:", err);
    return [];
  }
}

// ---------------------------------------------
// AUTH API
// ---------------------------------------------
export async function register(email, password) {
  const res = await fetch(`${API_BASE}/auth/register`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ email, password })
  });

  return await res.json(); // { success, message }
}

export async function loginApi(email, password) {
  const res = await fetch(`${API_BASE}/auth/login`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ email, password })
  });

  return await res.json(); // { success, token }
}

// ---------------------------------------------
// ORDER API (Requires JWT Token)
// ---------------------------------------------
export async function placeOrder(orderRequest) {
  const token = localStorage.getItem("token"); // JWT token

  const res = await fetch(`${API_BASE}/orders`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "Authorization": "Bearer " + token
    },
    body: JSON.stringify(orderRequest)
  });

  if (!res.ok) {
    throw new Error("Order failed");
  }

  return await res.json();
}
